def priority(item: float, bins: np.ndarray) -> np.ndarray:
    remaining = bins - item
    return np.where(remaining >= 0, 1.0 / (1.0 + remaining), -np.inf)

def priority(item: float, bins: np.ndarray) -> np.ndarray:
    remaining = bins - item
    target = 0.1 * bins.max() if len(bins) > 0 else 0.1
    return np.where(remaining >= 0, -np.abs(remaining - target), -np.inf)

def priority(item: float, bins: np.ndarray) -> np.ndarray:
    remaining = bins - item
    optimal_target = 0.5 * bins.max() if len(bins) > 0 else 0.5
    return np.where(remaining >= 0, np.exp(-((remaining - optimal_target) ** 2)), -np.inf)

def priority(item: float, bins: np.ndarray) -> np.ndarray:
    remaining = bins - item
    return np.where(remaining >= 0, remaining, -np.inf)
